begin;
set local search_path=public,extensions;
select plan(40);

select ok((select count(*)=16 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public'and c.relkind='r'and c.relname=any(array['marketing_consents','brand_kits','brand_kit_versions','marketing_templates','marketing_template_versions','social_connections','marketing_campaigns','marketing_content','marketing_content_versions','marketing_content_sources','marketing_calendar_items','marketing_exceptions','social_publication_jobs','social_publication_results','marketing_attribution_events','marketing_metric_events'])),'sixteen marketing domain tables exist');
select ok((select count(*)=16 and bool_and(c.relrowsecurity)from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public'and c.relname=any(array['marketing_consents','brand_kits','brand_kit_versions','marketing_templates','marketing_template_versions','social_connections','marketing_campaigns','marketing_content','marketing_content_versions','marketing_content_sources','marketing_calendar_items','marketing_exceptions','social_publication_jobs','social_publication_results','marketing_attribution_events','marketing_metric_events'])),'RLS is enabled on every marketing table');
select ok((select count(*)=16 from pg_policies where schemaname='public'and tablename=any(array['marketing_consents','brand_kits','brand_kit_versions','marketing_templates','marketing_template_versions','social_connections','marketing_campaigns','marketing_content','marketing_content_versions','marketing_content_sources','marketing_calendar_items','marketing_exceptions','social_publication_jobs','social_publication_results','marketing_attribution_events','marketing_metric_events'])),'every marketing table has one scoped read policy');
select ok(not has_table_privilege('authenticated','public.marketing_campaigns','INSERT')and not has_table_privilege('authenticated','public.marketing_consents','UPDATE')and not has_table_privilege('authenticated','public.social_publication_jobs','INSERT'),'authenticated users cannot bypass marketing RPCs');
select ok(not has_table_privilege('service_role','public.marketing_campaigns','INSERT')and not has_table_privilege('service_role','public.marketing_metric_events','INSERT'),'service role has no broad direct marketing writes');
select ok((select count(*)=5 and bool_and(p.prosecdef and p.proconfig::text like'%search_path=%')from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname=any(array['record_marketing_consent','create_marketing_campaign','approve_marketing_campaign','schedule_marketing_campaign','record_marketing_metric'])),'five marketing commands are security definer with fixed search paths');
select ok(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname like'%marketing%'and has_function_privilege('anon',p.oid,'EXECUTE')),'anonymous role cannot execute marketing functions');
select ok((select count(*)=5 and bool_and(has_function_privilege('authenticated',p.oid,'EXECUTE'))from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname=any(array['record_marketing_consent','create_marketing_campaign','approve_marketing_campaign','schedule_marketing_campaign','record_marketing_metric'])),'authenticated actors can invoke the five narrow commands');
select ok((select column_default like'%ASSISTED%'from information_schema.columns where table_schema='public'and table_name='marketing_campaigns'and column_name='mode'),'campaign mode defaults to ASSISTED');
select ok(exists(select 1 from pg_constraint where conrelid='public.marketing_templates'::regclass and contype='c'and pg_get_constraintdef(oid)like all(array['%PROBLEM_SOLUTION%','%EXPERT_TIP%','%PROVIDER_INTRO%','%BEFORE_AFTER%','%SERVICE_OF_MONTH%','%SUCCESS_CASE%'])),'the six Gold Master template families are constrained');
select ok(exists(select 1 from pg_constraint where conrelid='public.marketing_content_versions'::regclass and contype='c'and pg_get_constraintdef(oid)like'%FR%'and pg_get_constraintdef(oid)like'%AR%'),'content language is constrained to FR or AR');
select ok(exists(select 1 from pg_trigger where tgname='marketing_consents_immutable'and not tgisinternal),'consent history is append-only');
select ok((select count(*)=7 from pg_trigger where tgname=any(array['marketing_consents_immutable','brand_versions_immutable','template_versions_immutable','content_sources_immutable','publication_results_immutable','attribution_events_immutable','metric_events_immutable'])and not tgisinternal),'seven marketing histories are immutable');
select ok((select pg_get_functiondef(p.oid)like'%CLIENT_OWNER%'and pg_get_functiondef(p.oid)like'%FRANCHISE_MANAGER%'and pg_get_functiondef(p.oid)like'%MATRICIA_ADMIN%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private'and p.proname='marketing_manage_access'),'marketing management is role and tenant scoped');
select ok((select pg_get_functiondef(p.oid)like'%order by decided_at desc,id desc limit 1%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private'and p.proname='marketing_consent_active'),'active consent is derived from the latest immutable decision');
select ok((select pg_get_functiondef(p.oid)like'%begin_contract_command%'and pg_get_functiondef(p.oid)like'%finish_contract_command%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='record_marketing_consent'),'consent recording is idempotent');
select ok((select pg_get_functiondef(p.oid)like'%status=''SKIPPED''%'and pg_get_functiondef(p.oid)like'%decision=''WITHDRAWN''%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='record_marketing_consent'),'withdrawal skips queued publication work');
select ok((select pg_get_functiondef(p.oid)like'%audit_events%'and pg_get_functiondef(p.oid)like'%event_outbox%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='record_marketing_consent'),'consent changes are audited and emit Outbox');
select ok((select pg_get_functiondef(p.oid)like'%p_mode=''AUTOPILOT''%'and pg_get_functiondef(p.oid)like'%marketing_consent_active%'and pg_get_functiondef(p.oid)like'%social_connections%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='create_marketing_campaign'),'AUTOPILOT creation requires consent and an active connection');
select ok((select pg_get_functiondef(p.oid)like'%brand_kit_version%'and pg_get_functiondef(p.oid)like'%status<>''READY''%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='create_marketing_campaign'),'campaign creation requires a ready versioned Brand Kit');
select ok((select pg_get_functiondef(p.oid)like'%begin_contract_command%'and pg_get_functiondef(p.oid)like'%MarketingCampaignCreatedV1%'and pg_get_functiondef(p.oid)like'%audit_events%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='create_marketing_campaign'),'campaign creation is idempotent audited and emits Outbox');
select ok((select pg_get_functiondef(p.oid)like'%VALIDATED_BY_RULES%'and pg_get_functiondef(p.oid)like'%severity=''BLOCKING''%'and pg_get_functiondef(p.oid)like'%status=''OPEN''%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='approve_marketing_campaign'),'human approval rejects unvalidated campaigns and blocking exceptions');
select ok((select pg_get_functiondef(p.oid)like'%row_version<>p_expected_row_version%'and pg_get_functiondef(p.oid)like'%STALE_MARKETING_CAMPAIGN%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='approve_marketing_campaign'),'approval uses optimistic concurrency');
select ok((select pg_get_functiondef(p.oid)like'%approved_by=a%'and pg_get_functiondef(p.oid)like'%MarketingCampaignApprovedV1%'and pg_get_functiondef(p.oid)like'%audit_events%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='approve_marketing_campaign'),'approval records the human actor and emits audit plus Outbox');
select ok((select pg_get_functiondef(p.oid)like'%marketing_consent_active%'and pg_get_functiondef(p.oid)like'%SOCIAL_PUBLISHING%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='schedule_marketing_campaign'),'scheduling rechecks current publishing consent');
select ok((select pg_get_functiondef(p.oid)like'%risk_score>c.risk_threshold%'and pg_get_functiondef(p.oid)like'%jsonb_each_text(v.compliance_checks)%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='schedule_marketing_campaign'),'scheduling blocks excess risk and failed compliance checks');
select ok((select pg_get_functiondef(p.oid)like'%MARKETING_FREQUENCY_LIMIT%'and pg_get_functiondef(p.oid)like'%frequency_max_weekly%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='schedule_marketing_campaign'),'scheduling enforces a campaign frequency cap');
select ok((select pg_get_functiondef(p.oid)like'%social_publication_jobs%'and pg_get_functiondef(p.oid)like'%SocialPublicationScheduledV1%'and pg_get_functiondef(p.oid)not like'%http%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='schedule_marketing_campaign'),'scheduling queues provider-neutral Outbox work without inline social calls');
select ok((select pg_get_functiondef(p.oid)like'%begin_contract_command%'and pg_get_functiondef(p.oid)like'%finish_contract_command%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='schedule_marketing_campaign'),'schedule mutation is idempotent');
select ok(exists(select 1 from pg_constraint where conrelid='public.marketing_content_sources'::regclass and contype='c'and pg_get_constraintdef(oid)like'%ANOMALY_AGGREGATE%'and pg_get_constraintdef(oid)like'%aggregate_size >= 10%'),'anomaly-derived content enforces k-anonymity of ten');
select ok((select data_type='bigint'from information_schema.columns where table_schema='public'and table_name='marketing_metric_events'and column_name='value_minor'),'marketing financial values use exact bigint minor units');
select ok(exists(select 1 from pg_constraint where conrelid='public.marketing_metric_events'::regclass and contype='c'and pg_get_constraintdef(oid)like'%value_minor%'and pg_get_constraintdef(oid)like'%currency%'),'financial metric amount and currency are structurally paired');
select ok((select pg_get_functiondef(p.oid)like'%begin_contract_command%'and pg_get_functiondef(p.oid)like'%audit_events%'and pg_get_functiondef(p.oid)like'%MarketingMetricRecordedV1%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='record_marketing_metric'),'metric feedback is idempotent audited and emits Outbox');
select ok(exists(select 1 from pg_trigger where tgname='attribution_events_immutable'and not tgisinternal),'multi-touch attribution events are immutable');
select ok((select reloptions@>array['security_invoker=true']from pg_class where oid='public.marketing_campaign_performance'::regclass),'performance feedback view respects caller RLS');
select ok((select pg_get_viewdef('public.marketing_campaign_performance'::regclass,true)like'%CHANGE_TEMPLATE%'and pg_get_viewdef('public.marketing_campaign_performance'::regclass,true)like'%INCREASE_FREQUENCY%'and pg_get_viewdef('public.marketing_campaign_performance'::regclass,true)like'%PAUSE_CAMPAIGN%'),'KPI feedback exposes bounded campaign recommendations');
select ok((select qual like'%marketing_manage_access%'from pg_policies where schemaname='public'and tablename='marketing_campaigns'),'campaign reads are tenant and role scoped');
select ok((select qual like'%has_platform_role%'and qual not like'%marketing_manage_access%'from pg_policies where schemaname='public'and tablename='marketing_templates'),'global template library is platform-admin/auditor only');
select ok(exists(select 1 from pg_constraint where conrelid='public.social_connections'::regclass and contype='c'and pg_get_constraintdef(oid)like'%!~*%'and pg_get_constraintdef(oid)like'%token%'),'social connection rejects obvious inline secret references case-insensitively');
select ok((select count(*)=8 from pg_indexes where schemaname='public'and indexname=any(array['marketing_consents_current_idx','campaigns_org_status_idx','content_campaign_idx','content_versions_status_idx','calendar_schedule_idx','publication_jobs_queue_idx','attribution_campaign_time_idx','metrics_campaign_time_idx'])),'marketing read queue and feedback paths are indexed');

select * from finish();
rollback;
